def remove_Occ(s: str, ch: str) -> str:
    first_occurrence = s.find(ch)
    last_occurrence = s.rfind(ch)

    new_string = list(s)

    if first_occurrence != -1:
        new_string[first_occurrence] = ''

    if last_occurrence != -1 and last_occurrence != first_occurrence:
        new_string[last_occurrence] = ''
    elif last_occurrence != -1 and last_occurrence == first_occurrence and first_occurrence != len(s) -1:
        new_string[last_occurrence] = ''


    return "".join(new_string)


