import heapq
from collections import Counter

def func(nums: list[list[int]], k: int) -> list[int]:
    counts = Counter()
    for sublist in nums:
        for num in sublist:
            counts[num] += 1

    heap = []
    for num, count in counts.items():
        heapq.heappush(heap, (-count, num))

    result = []
    for _ in range(min(k, len(counts))):
        count, num = heapq.heappop(heap)
        result.append(num)

    return sorted(result, key=lambda x: (-counts[x], x))


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, func([[1,1,1,2,2,3], [4,4,5,5,5]], 2), [5, 1])
    check(2, func([[1,2,3], [4,5,6]], 3), [1, 2, 3])
    check(3, func([[1,1,2,2,3,3,3]], 1), [3])
    check(4, func([[1, 1, 2, 2, 2, 3, 3]], 2), [2, 3])
    check(5, func([[5, 5, 4, 4, 3, 3, 3, 2, 2, 1]], 2), [3, 2])

def max_Prime_Factors (n: int) -> int:
    """একটি প্রদত্ত সংখ্যার বৃহত্তম প্রধান গুণক খুঁজে পেতে একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to find the largest prime factor of a given number."""
    maxPrime = -1
    while n % 2 == 0:
        maxPrime = 2
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            maxPrime = i
            n //= i
    if n > 2:
        maxPrime = n
    return maxPrime

