def div_even_odd(list1: list[int]) -> int:
    """একটি প্রদত্ত তালিকার প্রথম সম এবং অদ্ভুত সংখ্যার বিভাজন খুঁজে বের করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to find the division result of the first even and odd numbers in a given list."""
    first_even = None
    first_odd = None
    for num in list1:
        if first_even is None and num % 2 == 0:
            first_even = num
        if first_odd is None and num % 2 != 0:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    if first_even is None or first_odd is None:
        return 0
    if first_odd == 0:
        return 0
    return first_even // first_odd


