def compute_Last_Digit(A: int, B: int) -> int:
    """একটি পাইথন ফাংশন লিখুন যখন a এর ফ্যাক্টরিয়াল b এর ফ্যাক্টরিয়ালকে ভাগ করে দেয় তখন শেষ অঙ্কটি খুঁজে বের করতে।"""
    """Translated: Write a Python function to find the last digit when the factorial of `a` divides the factorial of `b`."""
    if A > B:
        return 0
    else:
        fact_a = 1
        for i in range(1, A + 1):
            fact_a *= i
        fact_b = 1
        for i in range(1, B + 1):
            fact_b *= i
        if fact_b % fact_a == 0:
            return 1
        else:
            return 0

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

