def is_Monotonic(A: list[int]) -> bool:
    """প্রদত্ত অ্যারেটি একবচনীয় কিনা তা পরীক্ষা করার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to check if the given array is monotonic."""
    n = len(A)
    if n <= 2:
        return True

    increasing = True
    decreasing = True

    for i in range(1, n):
        if A[i] < A[i-1]:
            increasing = False
        if A[i] > A[i-1]:
            decreasing = False

    return increasing or decreasing

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
