def eulerian_num(n: int, m: int) -> int:
    if n == 0:
        return 0 if m > 0 else 1
    if m < 0 or m >= n:
        return 0

    result = 0
    for k in range(m + 1):
        result += ((-1)**k) * comb(n + 1, k) * ((m - k + 1)**n)
    return result

def comb(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k
    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

