    """একটি বাইনারি স্ট্রিং এর ঘূর্ণন সংখ্যা খুঁজে বের করার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to find the number of rotations of a binary string that are odd-equivalent."""
    count = 0
    for i in range(n):
        rotated_string = s[i:] + s[:i]
        odd_ones = 0
        for j in range(n):
            if (j + 1) % 2 != 0 and rotated_string[j] == '1':
                odd_ones += 1
        if odd_ones % 2 != 0:
            count += 1
    return count

