def amicable_numbers_sum(limit: int) -> int:
    """১ থেকে নির্দিষ্ট সংখ্যার মধ্যে থাকা সব বন্ধুত্বপূর্ণ সংখ্যার যোগফলের জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to calculate the sum of all amicable numbers within a given limit, exclusively."""
    def sum_divisors(n):
        sum_ = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                sum_ += i
                if i * i != n:
                    sum_ += n // i
        return sum_

    amicable_sum = 0
    for a in range(2, limit):
        b = sum_divisors(a)
        if a != b and b < limit and sum_divisors(b) == a:
            amicable_sum += a
    return amicable_sum


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, amicable_numbers_sum(1000), 504)
    check(2, amicable_numbers_sum(2000), 2844)
    check(3, amicable_numbers_sum(10000), 31626)

def find_length(string: str, n: int) -> int:
    max_diff = 0
    current_diff = 0
    for i in range(n):
        if string[i] == '0':
            current_diff += 1
        else:
            current_diff -= 1
        if current_diff < 0:
            current_diff = 0
        max_diff = max(max_diff, current_diff)
    return max_diff


