def sum(a: int, b: int) -> int:
    """দুটি প্রদত্ত সংখ্যার সাধারণ বিভাজকগুলির যোগফল খুঁজে বের করার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to find the sum of the common divisors of two given numbers."""

    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    g = gcd(a, b)
    divisors_sum = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            divisors_sum += i
            if i * i != g:
                divisors_sum += g // i
        i += 1
    return divisors_sum


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
