            return "even"
        else:
            return "odd"

    if n == 0:
        if last_element % 2 == 0:
            return "even"
        else:
            return "odd"

    if p % 2 == 0:
        if last_element % 2 == 0:
            return "even"
        else:
            return "odd"
    else:
        if arr_sum % 2 == 0:
            return "even"
        else:
            return "odd"

