def cal_electbill(units: int) -> float:
    """বিদ্যুৎ বিল গণনা করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to calculate electricity bill."""
    if units <= 50:
        bill = units * 0.5
    elif units <= 150:
        bill = 50 * 0.5 + (units - 50) * 0.75
    elif units <= 250:
        bill = 50 * 0.5 + 100 * 0.75 + (units - 150) * 1.20
    else:
        bill = 50 * 0.5 + 100 * 0.75 + 100 * 1.20 + (units - 250) * 1.50
    return float(bill)

