def pancake_sort(nums: list[int]) -> list[int]:
    arr = nums[:]
    n = len(arr)
    for i in range(n, 1, -1):
        mi = arr.index(max(arr[:i]))
        if mi != i - 1:
            arr[:mi + 1] = arr[:mi + 1][::-1]
            arr[:i] = arr[:i][::-1]
    return arr

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

