def max_path_sum(tri: list[list[int]], m: int, n: int) -> int:
    dp = [0] * n
    for i in range(n):
        dp[i] = tri[m - 1][i]

    for i in range(m - 2, -1, -1):
        for j in range(i + 1):
            dp[j] = tri[i][j] + max(dp[j], dp[j + 1])
    return dp[0]


