def encode_list(list1: list) -> list:
    """একটি তালিকা থেকে রান-লংথ এনকোডিং প্রতিফলিত করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to perform run-length encoding on a list."""
    if not list1:
        return []

    encoded_list = []
    count = 1
    current_element = list1[0]

    for i in range(1, len(list1)):
        if list1[i] == current_element:
            count += 1
        else:
            if count > 1:
                encoded_list.append([count, current_element])
            else:
                encoded_list.append(current_element)
            current_element = list1[i]
            count = 1

    if count > 1:
        encoded_list.append([count, current_element])
    else:
        encoded_list.append(current_element)

    return encoded_list


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, encode_list(['A', 'A', 'A', 'A', 'B', 'C', 'C', 'A', 'A', 'D', 'E', 'E', 'E', 'E']), [[4, 'A'], 'B', [2, 'C'], [2, 'A'], 'D', [4, 'E']])
