def solution(a: int, b: int, n: int) -> tuple:
    """একটি ফাংশন লিখুন x এবং y এর জন্য যা ax + by = n পূরণ করে।"""
    """Translated: Write a function for x and y that satisfies ax + by = n."""
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if a * x + b * y == n:
                return (x, y)
    return (None, None)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

