def is_valid_parenthese(str1: str) -> bool:
    """একটি ফাংশন লিখুন যা বন্ধনীগুলির স্ট্রিংয়ের বৈধতা যাচাই করে।"""
    """Translated: Write a function that checks the validity of a string of parentheses."""
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in str1:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
