def first(arr: list[int], x: int, n: int) -> int:
    l = 0
    r = n - 1
    first_occurrence = -1

    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == x:
            first_occurrence = mid
            r = mid - 1  # Look for first occurrence in the left half
        elif arr[mid] < x:
            l = mid + 1
        else:
            r = mid - 1

    return first_occurrence


