    """একটি রান-লংথ এনকোডযুক্ত তালিকা ডিকোড করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to decode a run-length encoded list."""
    res = []
    if not alist:
        return res
    for i in range(0, len(alist), 2):
        if i + 1 < len(alist):
            freq = alist[i]
            val = alist[i+1]
            if isinstance(freq, int) and freq > 0:
                res.extend([val] * freq)
    return res

