def replace_max_specialchar(text: str, n: int) -> str:
    pattern = r'[ ,.]'
    count = 0

    def replace(match):
        nonlocal count
        if count < n:
            count += 1
            return ':'
        else:
            return match.group(0)

    return re.sub(pattern, replace, text)

