def get_total_number_of_sequences(m: int, n: int) -> int:
    dp = {}

    def solve(prev, k):
        if k == n:
            return 1
        if (prev, k) in dp:
            return dp[(prev, k)]

        count = 0
        start = 2 * prev if prev != 0 else 1
        for i in range(start, m + 1):

            count += solve(i, k + 1)

        dp[(prev, k)] = count
        return count

    return solve(0, 0)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
