def lps(str: str) -> int:
    n = len(str)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if str[i] == str[j]:
                if i + 1 <= j - 1:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j] if i + 1 < n else 0)
    return dp[0][n - 1]


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
