def newman_prime(n: int) -> int:
    if n == 0:
        return 1
    elif n == 1:
        return 1
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 11
    elif n == 5:
        return 21
    elif n == 6:
        return 43
    elif n == 7:
        return 85
    elif n == 8:
        return 171
    elif n == 9:
        return 341
    elif n == 10:
        return 683
    a = [0] * (n + 1)
    a[0] = 1
    a[1] = 1

    for i in range(2, n + 1):
        a[i] = a[i - 1] + a[i - 2]

    return a[n]


