def validate(n: int) -> bool:
    counts = {}
    for digit in str(n):
        digit = int(digit)
        counts[digit] = counts.get(digit, 0) + 1

    for digit, count in counts.items():
        if digit == 0 and count > 0:
            return False
        if count > digit:
            return False
    return True

