def count_binary_seq(n: int) -> float:
    def factorial(num):
        if num == 0:
            return 1
        else:
            result = 1
            for i in range(1, num + 1):
                result *= i
            return result

    def combinations(n, k):
        if k < 0 or k > n:
            return 0
        return factorial(n) // (factorial(k) * factorial(n - k))

    count = 0
    for i in range(n + 1):
        count += combinations(n, i) ** 2
    return float(count)

