def max_sum_increasing_subseq(a: list[int], n: int, index: int, k: int) -> int:
    dp = [0] * (index + 1)
    for i in range(index + 1):
        dp[i] = a[i]
        for j in range(i):
            if a[i] > a[j]:
                dp[i] = max(dp[i], dp[j] + a[i])

    max_so_far = max(dp)

    if k > index and k < n:
        temp_max = 0
        for i in range(index + 1):
            if a[k] > a[i]:
                temp_max = max(temp_max, dp[i])

        if temp_max > 0:
            return max(max_so_far, temp_max + a[k])
        else:
            can_add = True
            for i in range(index + 1):
                if a[k] <= a[i]:
                    can_add = False
                    break
            if can_add:
                return max(max_so_far, a[k])
            else:
                return max_so_far
    return max_so_far


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
