def set_left_most_unset_bit(n: int) -> int:
    """বাম সবচেয়ে অসত বিট সেট করার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to set the leftmost unset bit."""
    if n == 0:
        return 1

    msb = 0
    temp = n
    while temp > 0:
        temp = temp >> 1
        msb += 1

    if (1 << msb) - 1 == n:
      return n | (1 << msb)


    i = msb - 1

    while i >= 0:
        if (n >> i) & 1 == 0:
            return n | (1 << i)
        i -= 1

    return n | (1 << msb)


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

