def find_last_occurrence(A: list[int], x: int) -> int:
    left = 0
    right = len(A) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if A[mid] == x:
            result = mid
            left = mid + 1
        elif A[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    return result


