def modified_encode(alist: list) -> list:
    """একটি তালিকা থেকে পরিবর্তিত রান-লংথ এনকোডিং প্রতিফলিত করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function to return the modified run-length encoding from a list."""
    res = []
    if not alist:
        return res

    count = 1
    for i in range(1, len(alist)):
        if alist[i] == alist[i - 1]:
            count += 1
        else:
            if count == 1:
                res.append(alist[i - 1])
            else:
                res.append((count, alist[i - 1]))
            count = 1

    if count == 1:
        res.append(alist[-1])
    else:
        res.append((count, alist[-1]))

    return res


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"


