    """Translated: Write a function to find the word with the most occurrences in a given list of strings."""
    if not test_list:
        return ""
    counts = {}
    for item in test_list:
        counts[item] = counts.get(item, 0) + 1

    max_count = 0
    most_frequent = None
    for item, count in counts.items():
        if count > max_count:
            max_count = count
            most_frequent = item
        elif count == max_count:
            if most_frequent is None or item < most_frequent:
                most_frequent = item

    return most_frequent

