def find_Divisor(x: int, y: int) -> int:
    """একটি অন্তরালের সর্বাধিক ঘটনাকারী বিভাজক খুঁজে পেতে একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to find the highest occurring divisor within a given range."""
    counts = {}
    for i in range(x, y + 1):
        for j in range(1, int(i**0.5) + 1):
            if i % j == 0:
                counts[j] = counts.get(j, 0) + 1
                if j * j != i:
                    counts[i // j] = counts.get(i // j, 0) + 1

    if not counts:
        return 0

    max_count = 0
    divisor = -1
    for k, v in counts.items():
        if v > max_count:
            max_count = v
            divisor = k
        elif v == max_count:
            divisor = max(divisor, k)
    return divisor

