def bin_coff(n: int) -> int:
    """একটি ফাংশন লিখুন যা প্রদত্ত দৈর্ঘ্যের ক্রমগুলি গণনা করে যার অ-নেতিবাচক উপসর্গ যোগফল রয়েছে যা প্রদত্ত মান দ্বারা উত্পন্ন হতে পারে।"""
    """Translated: Write a function that calculates the number of sequences of a given length that have non-negative prefix sums that can be generated by a given value."""
    if n < 0:
        return 0
    if n == 0:
        return 1
    res = 1
    for i in range(n):
        res = res * (2 * n - i) // (i + 1)
    return res // (n + 1)

