def make_flip(ch: str) -> int:
    count0 = 0
    count1 = 0
    for i in range(len(ch)):
        if i % 2 == 0:
            if ch[i] == '1':
                count0 += 1
            if ch[i] == '0':
                count1 += 1
        else:
            if ch[i] == '0':
                count0 += 1
            if ch[i] == '1':
                count1 += 1
    return min(count0, count1)

