import heapq

def k_smallest_pairs(nums1: list[int], nums2: list[int], k: int) -> list[list[int]]:
    heap = []
    for i in range(min(len(nums1), k)):
        for j in range(min(len(nums2), k)):
            heapq.heappush(heap, (nums1[i] + nums2[j], nums1[i], nums2[j]))

    result = []
    for _ in range(min(k, len(nums1) * len(nums2))):
        if heap:
            _, num1, num2 = heapq.heappop(heap)
            result.append([num1, num2])

    return result

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
