def max_Product(arr: list[int]) -> tuple[int, int]:
    n = len(arr)
    if n < 2:
        return None

    max1 = arr[0]
    max2 = arr[1]

    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] * arr[j] > max1 * max2:
                max1 = arr[i]
                max2 = arr[j]

    return (min(max1, max2), max(max1,max2))


