def group_tuples(Input: list[tuple]) -> list[tuple]:
    """একটি ফাংশন লিখুন যা টিপল তালিকার সাধারণ প্রথম উপাদান খুঁজে বের করে।"""
    """Translated: Write a function that finds the common first element of a list of tuples."""
    if not Input:
        return []

    first_elements = {}
    for tup in Input:
        first_element = tup[0]
        if first_element in first_elements:
            first_elements[first_element].append(tup)
        else:
            first_elements[first_element] = [tup]

    result = []
    for key, value in first_elements.items():
        result.append((key, value))

    return result


