def find_adverb_position(text: str) -> tuple[int, int, str]:
    match = re.search(r'\b(\w+ly)\b', text)
    if match:
        start = match.start(1)
        end = match.end(1)
        adverb = match.group(1)
        return (start, end, adverb)
    else:
        return (0, 0, "")

