def max_product(arr: list[int], n: int) -> int:
    if n == 0:
        return 0

    dp = [arr[i] for i in range(n)]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] * arr[i], arr[i])

    max_so_far = 0
    for i in range(n):
        max_so_far = max(max_so_far, dp[i])

    return max_so_far

