def max_profit(price: list[int], k: int) -> int:
    """একটি ফাংশন লিখুন যা সর্বোচ্চ k টি স্টক লেনদেন থেকে সর্বাধিক লাভের পরিমাণ খুঁজে বের করে"""
    """Translated: Write a function that finds the maximum profit that can be made from at most k stock transactions."""
    n = len(price)
    if n <= 1:
        return 0

    if k >= n // 2:
        profit = 0
        for i in range(1, n):
            diff = price[i] - price[i - 1]
            if diff > 0:
                profit += diff
        return profit

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -price[0]
        for j in range(1, n):
            dp[i][j] = dp[i][j-1]
            max_diff = max(max_diff, dp[i-1][j-1] - price[j-1])
            dp[i][j] = max(dp[i][j], price[j] + max_diff)

    return dp[k][n - 1]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, max_profit([2, 4, 1], 2), 2)
    check(2, max_profit([3, 2, 6, 5, 0, 3], 2), 7)
    check(3, max_profit([3,3,5,0,0,3,1,4], 2), 6)
    check(4, max_profit([1,2,4,2,5,7,2,4,9,0], 2), 11)

