def is_subset_sum(set: list[int], n: int, sum: int) -> bool:
    dp = [[False for _ in range(sum + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, sum + 1):
            if set[i - 1] <= j:
                dp[i][j] = dp[i - 1][j - set[i - 1]] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][sum]


