def binary_search(item_list: list[int], item: int) -> bool:
    low = 0
    high = len(item_list) - 1

    while low <= high:
        mid = (low + high) // 2
        if item_list[mid] == item:
            return True
        elif item < item_list[mid]:
            high = mid - 1
        else:
            low = mid + 1

    return False


