def min_cost(cost: list[list[int]], m: int, n: int) -> int:
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    dp[0][0] = cost[0][0]

    for i in range(1, m + 1):
        dp[i][0] = dp[i - 1][0] + cost[i][0]

    for j in range(1, n + 1):
        dp[0][j] = dp[0][j - 1] + cost[0][j]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i-1][j-1]) + cost[i][j]

    return dp[m][n]

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    cost = [[1, 2, 3], [4, 8, 2], [1, 5, 3]]
    check(1, min_cost(cost, 2, 2), 12)

    cost = [[1, 3, 5, 8], [4, 2, 1, 7], [4, 3, 2, 3]]
    check(2, min_cost(cost, 2, 3), 12)

    cost = [[2, 5], [7, 1]]
    check(3, min_cost(cost, 1, 1), 8)

    cost = [[1, 2, 3], [4, 5, 6]]
    check(4, min_cost(cost, 1, 2), 12)

def similar_elements(test_tup1: tuple, test_tup2: tuple) -> tuple:
    """প্রদত্ত দুটি টিপল তালিকা থেকে অনুরূপ উপাদানগুলি খুঁজে পেতে একটি ফাংশন লিখুন।"""
    """Translated: Write a function to find the similar elements from two given tuple lists."""
    return tuple(set(test_tup1) & set(test_tup2))


def check(test_id, test_val, expected):
