def is_not_prime(n: int) -> bool:
    """অ-প্রাইম সংখ্যা চিহ্নিত করার জন্য একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to identify non-prime numbers."""
    if n <= 1:
        return True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, is_not_prime(1), True)
    check(2, is_not_prime(4), True)
    check(3, is_not_prime(5), False)
    check(4, is_not_prime(12), True)
    check(5, is_not_prime(29), False)

import heapq

def heap_queue_largest(nums: list[int], n: int) -> list[int]:
    """হিপ ক্যু অ্যালগরিদম ব্যবহার করে সংখ্যার একটি তালিকা থেকে বৃহত্তম পূর্ণসংখ্যা খুঁজে বের করার জন্য একটি ফাংশন লিখুন।"""
    """Translated: Write a function using the heap queue algorithm to find the largest integers from a list of numbers."""
    return heapq.nlargest(n, nums)

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
