def find_Rotations(str: str) -> int:
    """একই স্ট্রিং পেতে প্রয়োজনীয় ন্যূনতম ঘূর্ণন সংখ্যা খুঁজে পেতে একটি পাইথন ফাংশন লিখুন।"""
    """Translated: Write a Python function to find the minimum number of rotations required to get the same string."""
    temp = str + str
    n = len(str)
    for i in range(1, n + 1):
        if (temp[i: i + n] == str):
            return i
    return n


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, find_Rotations("geeks"), 5)
    check(2, find_Rotations("aaaa"), 1)
    check(3, find_Rotations("abab"), 2)
    check(4, find_Rotations("abc"), 3)
